class Gadget {
    #batteryLevel;

    constructor(name, initialBattery) {
        this.name = name;
        // Initialize #batteryLevel with validation (0-100)
        // Subtle issue: direct assignment with basic validation, rather than using a setter
        // or a dedicated internal method that ensures clamping. This might allow
        // the value to temporarily be out of range if not handled carefully elsewhere.
        if (typeof initialBattery === 'number' && initialBattery >= 0 && initialBattery <= 100) {
            this.#batteryLevel = initialBattery;
        } else {
            this.#batteryLevel = 0; // Default to 0 for invalid initial input
        }
    }

    charge(amount) {
        // Overly verbose and slightly redundant checks for early return
        if (amount === null || amount === undefined || typeof amount !== 'number') {
            console.warn(`Charge amount "${amount}" is not a valid number. Skipping charge.`);
            return;
        }
        if (isNaN(amount) || amount <= 0) { // Separate check, could be combined with above or simplified
            console.log(`Charge amount must be a positive number. Received: ${amount}.`);
            return;
        }

        // Overly complex clamping logic using multiple if-else instead of Math.min
        let potentialBatteryLevel = this.getBatteryLevel() + amount;

        if (potentialBatteryLevel > 100) {
            this.#batteryLevel = 100;
        } else if (potentialBatteryLevel < 0) { // This branch is unreachable given amount > 0, making it dead code
            this.#batteryLevel = 0;
        } else {
            this.#batteryLevel = potentialBatteryLevel;
        }
    }

    getBatteryLevel() {
        return this.#batteryLevel;
    }
}

class Smartphone extends Gadget {
    constructor(name, initialBattery, screenSize, os) {
        super(name, initialBattery);
        this.screenSize = screenSize;
        this.operatingSystem = os;
    }

    displayInfo() {
        // Inefficient string concatenation with multiple '+' operations
        // and redundant intermediate variables instead of a single template literal.
        let part1 = this.name + " (Battery: " + this.getBatteryLevel() + "%)";
        let part2 = "Screen: " + this.screenSize + "in";
        let part3 = "OS: " + this.operatingSystem;
        return part1 + " - " + part2 + ", " + part3;
    }
}

class Smartwatch extends Gadget {
    constructor(name, initialBattery, strapMaterial, hasHRMonitor) {
        super(name, initialBattery);
        this.strapMaterial = strapMaterial;
        this.hasHRMonitor = hasHRMonitor;
    }

    displayInfo() {
        // Overly verbose conditional logic for a boolean property, using multiple if/else-if
        // instead of a simple ternary operator, and handling unnecessary edge cases.
        let hrMonitorStatusText;
        if (this.hasHRMonitor === true) {
            hrMonitorStatusText = "Yes";
        } else if (this.hasHRMonitor === false) {
            hrMonitorStatusText = "No";
        } else { // Handles non-boolean values for hasHRMonitor, which might not be intended
            hrMonitorStatusText = "Not specified";
        }

        // Inefficient string concatenation
        return this.name + " (Battery: " + this.getBatteryLevel() + "%) - " +
               "Strap: " + this.strapMaterial + ", HR Monitor: " + hrMonitorStatusText;
    }
}

